import { describe, it, expect } from "vitest";
import { processScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Base premiums / simplest cases ---
  it("empty item list -> premium 5 G (only processing fee)", () => {
    const result = processScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });
    expect(result.results[0]).toEqual({ premium: 5 });
  });
  it.todo("single sword -> premium 105 G (100 base + 5 fee)");
  it.todo("single amulet -> premium 65 G (60 base + 5 fee)");
  it.todo("single staff -> premium 85 G (80 base + 5 fee)");
  it.todo("single potion -> premium 45 G (40 base + 5 fee)");

  // --- Components and building blocks ---
  it.todo("single rune -> premium 30 G (25 base + 5 fee)");
  it.todo("2 runes -> 50 G base premium (55 with fee)");
  it.todo("3 runes -> 60 G base premium block applies (65 with fee)");
  it.todo("4 runes -> 100 G base premium no block (105 with fee)");
  it.todo("7 runes -> 175 G base premium (180 with fee)");
  it.todo("2 runes + 1 moonstone -> 75 G base premium no block different types (80 with fee)");
  it.todo("3 runes + 3 moonstones -> 120 G base premium two separate blocks (125 with fee)");

  // --- Item-specific modifiers ---
  it.todo("cursed sword newcomer -> premium 165 G (100 + 50 curse + 10 first + 5 fee)");
  it.todo("sword enchantment 5 -> high-enchantment surcharge applies");
  it.todo("sword enchantment 4 -> no high-enchantment surcharge");
  it.todo("sword enchantment 5 cursed -> both surcharges apply");

  // --- Policy-wide modifiers ---
  it.todo("customer exactly 2 years -> loyalty discount applies");
  it.todo("first insurance -> 10% initial assessment surcharge");
  it.todo("second contract onwards -> 15% follow-up discount");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword + plain amulet -> 215 G (160 base + 50 curse + 5 fee)");

  // --- Rounding ---
  it.todo("premium yielding 197.5 G -> 198 G rounded up (favor MHPCO)");

  // --- Integration examples ---
  it.todo("newcomer cursed sword steel ench 3 -> premium 165 G");
  it.todo("long-standing customer second contract cursed sword ench 7 -> premium 160 G");

  // --- Claim: standard reimbursement ---
  it.todo("regular sword damage 500 -> payout 400 G (full minus deductible)");
  it.todo("rune damage 200 -> payout 100 G (full minus deductible)");

  // --- Claim: special clauses ---
  it.todo("dragon sword ench 8 damage 1000 -> payout 400 G (high-ench 50% then deductible)");
  it.todo("dragon sword ench 9 damage 1000 -> payout 400 G (50% wins then deductible)");
  it.todo("dragon sword ench 5 damage 800 -> payout 700 G (dragon full then deductible)");
  it.todo("steel sword ench 9 damage 1000 -> payout 400 G (high-ench 50% then deductible)");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack sword 500 + amulet 300 -> payout 600 G (deductible per item)");

  // --- Claim: remainingCap ---
  it.todo("sword damage returns remainingCap (cap 2000)");

  // --- Multiple items of same type ---
  it.todo("two swords -> insurance sum 2000 cap 4000; both damaged separate deductibles");
  it.todo("two sword damages but only one sword insured -> non-zero exit / rejected");

  // --- Cap exhaustion ---
  it.todo("sword cap 2000; two claims 1500 each -> first payout 1400 rem 600, second payout 600 rem 0");
  it.todo("cursed sword modified premium does not raise cap (cap 2000)");

  // --- Rounding of payout ---
  it.todo("payout yielding 350.5 G -> 350 G rounded down (favor MHPCO)");

  // --- Edge cases / errors ---
  it.todo("quote with unknown item type -> non-zero exit, error to stderr, no results");
  it.todo("claim referencing item not in policy -> non-zero exit, error to stderr");
  it.todo("claim damage amount -200 -> non-zero exit, error to stderr");
});

