const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

interface Item {
  type: string;
}

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

const quotePremium = (items: Item[]): number => {
  let total = 0;
  for (const item of items) {
    const base = BASE_PREMIUMS[item.type];
    total += base + base * 0.1;
  }
  return Math.ceil(total + PROCESSING_FEE);
};

export const processScenario = (scenario: Scenario): { results: unknown[] } => {
  const results = scenario.steps.map((step) => ({
    premium: quotePremium(step.items),
  }));
  return { results };
};

