success.beforeFullFileContent:
const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

interface Item {
  type: string;
}

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

const FIRST_INSURANCE_RATE = 0.1;

const quotePremium = (items: Item[]): number => {
  const itemsTotal = items.reduce((sum, item) => {
    const base = BASE_PREMIUMS[item.type];
    return sum + base + base * FIRST_INSURANCE_RATE;
  }, 0);
  return Math.ceil(itemsTotal + PROCESSING_FEE);
};

export const processScenario = (scenario: Scenario): { results: unknown[] } => {
  const results = scenario.steps.map((step) => ({
    premium: quotePremium(step.items),
  }));
  return { results };
};

