const FIRST_INSURANCE_RATE = 0.1;
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const componentGroupBase = (count: number): number => {
  const blocks = Math.floor(count / BLOCK_SIZE);
  const remainder = count % BLOCK_SIZE;
  return blocks * BLOCK_BASE_PREMIUM + remainder * BASE_PREMIUMS.rune;
};

const basePremium = (items: Item[]): number => {
  const componentCounts: Record<string, number> = {};
  let total = 0;
  for (const item of items) {
    if (COMPONENT_TYPES.has(item.type)) {
      componentCounts[item.type] = (componentCounts[item.type] ?? 0) + 1;
    } else {
      total += BASE_PREMIUMS[item.type];
    }
  }
  for (const count of Object.values(componentCounts)) {
    total += componentGroupBase(count);
  }
  return total;
};

