const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

const FIRST_INSURANCE_RATE = 0.1;
const CURSE_RATE = 0.5;
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_UNIT_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const componentGroupBase = (count: number): number => {
  if (count === BLOCK_SIZE) {
    return BLOCK_BASE_PREMIUM;
  }
  return count * COMPONENT_UNIT_PREMIUM;
};

const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);

const itemBasePremium = (item: Item): number =>
  isComponent(item) ? COMPONENT_UNIT_PREMIUM : BASE_PREMIUMS[item.type];

const basePremium = (items: Item[]): number => {
  const componentCounts: Record<string, number> = {};
  let total = 0;
  for (const item of items) {
    if (isComponent(item)) {
      componentCounts[item.type] = (componentCounts[item.type] ?? 0) + 1;
    } else {
      total += itemBasePremium(item);
    }
  }
  for (const count of Object.values(componentCounts)) {
    total += componentGroupBase(count);
  }
  return total;
};

const itemSurcharges = (item: Item): number => {
  let surcharge = 0;
  if (item.cursed) {
    surcharge += itemBasePremium(item) * CURSE_RATE;
  }
  return surcharge;
};

const quotePremium = (items: Item[]): number => {
  const base = basePremium(items);
  const firstInsurance = base * FIRST_INSURANCE_RATE;
  const surcharges = items.reduce((sum, item) => sum + itemSurcharges(item), 0);
  return Math.ceil(base + firstInsurance + surcharges + PROCESSING_FEE);
};

export const processScenario = (scenario: Scenario): { results: unknown[] } => {
  const results = scenario.steps.map((step) => ({
    premium: quotePremium(step.items),
  }));
  return { results };
};

