  it.todo("rune damage 200 -> payout 100 G (full minus deductible)");

  // --- Claim: special clauses ---
  it.todo("dragon sword ench 8 damage 1000 -> payout 400 G (high-ench 50% then deductible)");
  it.todo("dragon sword ench 9 damage 1000 -> payout 400 G (50% wins then deductible)");
