const claimResult = (
  policy: Policy,
  damages: Damage[],
): { payout: number; remainingCap: number } => {
  const available = [...policy.items];
  const payout = damages.reduce((sum, damage) => {
    const index = available.findIndex((i) => i.type === damage.itemType);
    if (index === -1) {
      throw new Error(
        `Claim rejected: no insured ${damage.itemType} available for this damage`,
      );
    }
    const [item] = available.splice(index, 1);
    return sum + damagePayout(damage, item);
  }, 0);
  return { payout, remainingCap: policy.cap - payout };
};

