  if (index === -1) {
    throw new Error(
      `Claim rejected: no insured ${damage.itemType} available for this damage`,
    );
  }
  const [item] = available.splice(index, 1);
  return item;
};

const claimResult = (
  policy: Policy,
  damages: Damage[],
): { payout: number; remainingCap: number } => {
  const available = [...policy.items];
  const rawPayout = damages.reduce(
    (sum, damage) => sum + damagePayout(damage, consumeInsuredItem(available, damage)),
    0,
  );
  const payout = Math.min(rawPayout, policy.remainingCap);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};

export const processScenario = (scenario: Scenario): { results: unknown[] } => {
  let hasQuotedBefore = false;
  const policies: Record<number, Policy> = {};

  const results = scenario.steps.map((step, index) => {
    if (step.op === "quote") {
      const isFollowUp = hasQuotedBefore;
      hasQuotedBefore = true;
