        items: step.items,
        cap: insuranceSum(step.items) * CAP_MULTIPLIER,
      };
      return { premium: quotePremium(step.items, scenario.customer, isFollowUp) };
    }
    return claimResult(policies[step.policy], step.incident.damages);
  });
  return { results };
};

